use sqlx::Row;
use tpv_application::SyncContext;
use tpv_domain::ids::{DeviceId, TenantId};

use crate::error::StorageResult;
use crate::helpers::{format_time, parse_uuid};
use crate::store::SqliteStore;

impl SqliteStore {
    /// Returns the stable local tenant/device identity, creating it on first
    /// use. The identity must survive restarts so every event generated by this
    /// terminal belongs to the same device and can be retried from the outbox.
    pub async fn sync_context(&self) -> StorageResult<SyncContext> {
        if let Some(context) = self.read_identity().await? {
            return Ok(context);
        }
        let context = SyncContext {
            tenant_id: TenantId::new(),
            device_id: DeviceId::new(),
        };
        let created_at = format_time(time::OffsetDateTime::now_utc())?;
        sqlx::query(
            "INSERT INTO local_identity (id, tenant_id, device_id, created_at)
             VALUES (1, ?, ?, ?)
             ON CONFLICT(id) DO NOTHING",
        )
        .bind(context.tenant_id.to_string())
        .bind(context.device_id.to_string())
        .bind(created_at)
        .execute(self.pool())
        .await?;
        // If another process won the insert race, read the stored identity.
        self.read_identity()
            .await?
            .ok_or_else(|| crate::error::StorageError::InvalidData("local identity missing".into()))
    }

    async fn read_identity(&self) -> StorageResult<Option<SyncContext>> {
        let row = sqlx::query("SELECT tenant_id, device_id FROM local_identity WHERE id = 1")
            .fetch_optional(self.pool())
            .await?;
        let Some(row) = row else {
            return Ok(None);
        };
        Ok(Some(SyncContext {
            tenant_id: TenantId::from_uuid(parse_uuid(&row.try_get::<String, _>("tenant_id")?)?),
            device_id: DeviceId::from_uuid(parse_uuid(&row.try_get::<String, _>("device_id")?)?),
        }))
    }

    /// Returns the central device token stored during enrollment, if any.
    pub async fn device_token(&self) -> StorageResult<Option<String>> {
        let token = sqlx::query_scalar::<_, Option<String>>(
            "SELECT device_token FROM local_identity WHERE id = 1",
        )
        .fetch_optional(self.pool())
        .await?;
        Ok(token.flatten())
    }

    pub async fn save_device_enrollment(
        &self,
        token: &str,
        device_name: &str,
    ) -> StorageResult<()> {
        let enrolled_at = format_time(time::OffsetDateTime::now_utc())?;
        let result = sqlx::query(
            "UPDATE local_identity
             SET device_token = ?, device_name = ?, enrolled_at = ?
             WHERE id = 1",
        )
        .bind(token)
        .bind(device_name)
        .bind(enrolled_at)
        .execute(self.pool())
        .await?;
        if result.rows_affected() == 0 {
            return Err(crate::error::StorageError::NotFound(
                "local identity is not initialized".into(),
            ));
        }
        Ok(())
    }

    pub async fn clear_device_enrollment(&self) -> StorageResult<()> {
        sqlx::query(
            "UPDATE local_identity
             SET device_token = NULL, device_name = NULL, enrolled_at = NULL
             WHERE id = 1",
        )
        .execute(self.pool())
        .await?;
        Ok(())
    }

    /// Cursor of the last central event applied locally.
    pub async fn pull_cursor(&self) -> StorageResult<u64> {
        let cursor =
            sqlx::query_scalar::<_, i64>("SELECT pull_cursor FROM local_identity WHERE id = 1")
                .fetch_optional(self.pool())
                .await?;
        Ok(cursor
            .and_then(|value| u64::try_from(value).ok())
            .unwrap_or(0))
    }

    pub async fn save_pull_cursor(&self, cursor: u64) -> StorageResult<()> {
        let result = sqlx::query("UPDATE local_identity SET pull_cursor = ? WHERE id = 1")
            .bind(i64::try_from(cursor).unwrap_or(i64::MAX))
            .execute(self.pool())
            .await?;
        if result.rows_affected() == 0 {
            return Err(crate::error::StorageError::NotFound(
                "local identity is not initialized".into(),
            ));
        }
        Ok(())
    }
}
